cd <scratch>/scratchpad/ref && python3 -c "
from ref import statement; from scenarios import S
from decimal import Decimal as D
car={k:set() for k in ['r2_12','r2_8','r2_5','r3','r4','r5_rec','r5_pay','r6','r7']}
for sc in S:
  for r in sc['roster']:
    for desc,amt,fr in statement(sc,r):
      if fr=='FR-006' and desc.startswith('12%'): car['r2_12'].add(sc['id'])
      if fr=='FR-006' and desc.startswith('8%'): car['r2_8'].add(sc['id'])
      if fr=='FR-006' and desc.startswith('5%'): car['r2_5'].add(sc['id'])
      if fr=='FR-010': car['r3'].add(sc['id'])
      if fr=='FR-012': car['r4'].add(sc['id'])
      if desc=='Draw recovered' and amt!=0: car['r5_rec'].add(sc['id'])
      if desc=='Commission payable' and amt!=0: car['r5_pay'].add(sc['id'])
      if fr=='FR-016' and desc.startswith('Clawback:') and amt!=0: car['r6'].add(sc['id'])
      if 'excluded' in desc: car['r7'].add(sc['id'])
for k,v in car.items(): print(k, sorted(v))
qs={(sc['id'],r['quota']) for sc in S for r in sc['roster']}; print(sorted({q for _,q in qs}))
"

