    "splits": [{"repId": r, "percent": D(str(p))} for r, p in d["splits"]],
    "refunds": [{"amount": D(a), "date": str(dt)} for a, dt in d["refunds"]]}
def scenario(sc, description):
    out = {"id": sc["id"], "name": sc["name"], "description": description,
        "quarter": {"start": str(sc["quarter"][0]), "end": str(sc["quarter"][1])},
        "roster": [{"repId": r["id"], "name": r["name"], "quota": D(r["quota"]), "startDate": str(r["start"]),
                    "openingRecoverableBalance": D(r.get("opening", "0.00"))} for r in sc["roster"]],
        "deals": [deal(d) for d in sc["deals"]],
        "bookingQuarters": [{"quarter": {"start": str(b["quarter"][0]), "end": str(b["quarter"][1])},
            "reps": [{"repId": k, "quota": D(v[0]), "startDate": str(v[1])} for k, v in b["reps"].items()],
            "partners": [{"repId": p, "startDate": str(s)} for p, s in b["partners"]],
            "deals": [deal(d) for d in b["deals"]]} for b in sc.get("bq", [])]}
    return out
class Enc(json.JSONEncoder):
    def default(self, o):
        if isinstance(o, D): return float(o)
        return super().default(o)
def dump(sc, description):
    s = json.dumps(scenario(sc, description), indent=2, cls=Enc)
    # keep money at two decimals exactly as the Appendix states them
    import re
    s = re.sub(r'("(?:amount|quota|openingRecoverableBalance)": )(-?\d+)(\.\d+)?', lambda m: m.group(1) + str(D(m.group(2) + (m.group(3) or '')).quantize(D('0.01'))), s)
    return s + "\n"
if __name__ == "__main__":
    ids = sys.argv[3:]
    for sc in S:
        if sc["id"] in ids:
            open(f'{sys.argv[2]}/{sc["id"]}.json', 'w').write(dump(sc, f'Appendix A: {sc["name"]} (carries {sc["examples"]}).'))
