    }

    private static string FixtureAssembly()
    {
        for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
        {
            var candidate = Path.Combine(directory.FullName, "tools", "CommissionCalculator.Tools.Fixture",
                "bin", Configuration, "net10.0", "CommissionCalculator.Tools.Fixture.dll");
            if (File.Exists(candidate))
            {
                return candidate;
            }
        }

        throw new FileNotFoundException("The fixture assembly was not found; Tools.Tests builds it by project reference.");
    }

    private static (int ExitCode, string Console) RunTools(params string[] arguments)
    {
        var start = new ProcessStartInfo("dotnet")
        {
            RedirectStandardOutput = true,
            RedirectStandardError = true,
        };
        start.ArgumentList.Add(ToolsAssembly());
        foreach (var argument in arguments)
        {
            start.ArgumentList.Add(argument);
        }

        using var process = Process.Start(start) ?? throw new InvalidOperationException("dotnet did not start.");
        var console = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
        process.WaitForExit();
        return (process.ExitCode, console);
    }

    private static string ToolsAssembly() =>
        Path.Combine(AppContext.BaseDirectory, "CommissionCalculator.Tools.dll");

